import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.hw3Av5Vn.js";const s="/llamatron/assets/voice_leading_editor.DQM-tib6.svg",_=JSON.parse('{"title":"Voice Leading","description":"","frontmatter":{},"headers":[],"relativePath":"generators/VOICE_LEADING.md","filePath":"generators/VOICE_LEADING.md"}'),n={name:"generators/VOICE_LEADING.md"};function i(d,e,h,c,l,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="voice-leading" tabindex="-1">Voice Leading <a class="header-anchor" href="#voice-leading" aria-label="Permalink to &quot;Voice Leading&quot;">​</a></h1><p>Chords played in root position jump around: C, then G, then Am, each built up from its root, moves every note a long way. A pianist plays G with its B at the bottom and F with its C at the bottom, so that the notes barely move. A voice leading does that for you: the first chord of a clip plays as written, and each chord after takes the inversion and the octave whose notes move least from the chord before. Single notes, such as a bass line&#39;s, are left alone.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p><img src="'+s+'" alt="A voice leading&#39;s settings"></p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td>Name</td><td><code>Enter</code> renames it, and every chain using it follows.</td></tr><tr><td>Lowest octave, Highest octave</td><td>The chords stay within these octaves, shown in the set&#39;s octave labels, so that they don&#39;t drift up or down over a long piece. A chord no voicing fits plays as written.</td></tr><tr><td>Keep the root in the bass</td><td>Off by default. On, each chord&#39;s lowest written note stays where it is and only the notes above it are voiced, always above it, as a keyboard player plays beside a bass player. <code>Space</code> or <code>Enter</code> toggles it.</td></tr><tr><td>Restart</td><td>When it starts over, as <a href="./../GENERATORS#restart">Generators</a> describes; with &quot;on new scene&quot; or &quot;whole song&quot; a scene&#39;s first chord is voiced near the last chord before.</td></tr></tbody></table><h2 id="applying-the-generator" tabindex="-1">Applying the Generator <a class="header-anchor" href="#applying-the-generator" aria-label="Permalink to &quot;Applying the Generator&quot;">​</a></h2><p>Add the Voice Leading generator to a chain after a progression, as <code>voice_leading: name</code>, or put it on any clip of chords. <code>examples/learning/05_voice_leading.yml</code> plays three progressions in root position, inverted by hand with the chord editor&#39;s Inv. row, and voice-led; the last scene of <code>examples/learning/06_chord_progression_generator.yml</code> voice-leads its pad.</p>',7)])])}const v=t(n,[["render",i]]);export{_ as __pageData,v as default};
